// Re-validates the lead, strips anything unsafe, and labels it.
const raw = $input.first().json.body || {};
const line = (v, max) => String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const name = line(raw.name, 80);
const email = line(raw.email, 120);
const subject = line(raw.subject, 140);
const message = String(raw.message == null ? '' : raw.message).replace(/[\u0000-\u0009\u000b-\u001f\u007f]/g, '').trim().slice(0, 4000);

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const links = (message.match(/https?:\/\//gi) || []).length;
const spamWords = /(backlinks?|guest post|crypto|casino|viagra|forex|loan offer|seo services|rank your site|cheap traffic|whatsapp me|telegram)/i;
const spam = !name || !emailOk || message.length < 10 || /https?:\/\//i.test(name) || links > 2 || spamWords.test(name + ' ' + subject + ' ' + message);

const hay = (subject + ' ' + message).toLowerCase();
let category = 'General';
if (/(n8n|make\.com|zapier|automat|agent|webhook|chatbot|claude|workflow|pipeline|\bai\b)/.test(hay)) category = 'AI automation';
else if (/(woocommerce|shopify|store|e-?commerce|headless|checkout)/.test(hay)) category = 'E-commerce';
else if (/\bseo\b|search engine|rankings?|organic/.test(hay)) category = 'SEO / growth';
else if (/(wordpress|website|landing page|elementor|web ?app|react|next\.?js)/.test(hay)) category = 'Web build';

const signals = [];
if (message.length >= 200) signals.push('detailed brief');
if (/(\$|usd|£|€|budget|rs\.?\s?\d|pkr)/i.test(message)) signals.push('mentions budget');
if (/(asap|urgent|this week|next week|deadline|by (monday|friday|end of))/i.test(message)) signals.push('time pressure');
if (category !== 'General') signals.push(category.toLowerCase());
const priority = signals.length >= 3 ? 'HOT' : signals.length === 2 ? 'WARM' : 'NEW';

return [{ json: {
  spam, name, email, subject, message, category, priority, signals,
  safeName: esc(name), safeSubject: esc(subject || '(no subject)'), safeEmail: esc(email),
  safeMessage: esc(message).replace(/\n/g, '<br>'),
  receivedAt: new Date().toISOString(),
} }];
